20|export async function handleImagesPost(req: Request): Promise<Response> {
21|  let parsed: ImageRequest;
22|  try {
23|    parsed = parseImageRequest(await req.json());
24|  } catch {
25|    return Response.json(
26|      { status: "error", code: "bad_request", message: MSG_BAD_REQUEST } satisfies ImageResponse,
27|      { status: 400 },
28|    );
29|  }
30|
31|  let env;
32|  try {
33|    env = readImageEnv();
34|  } catch {
35|    return Response.json(
36|      { status: "error", code: "unavailable", message: MSG_UNAVAILABLE } satisfies ImageResponse,
37|      { status: 503 },
38|    );
39|  }
40|
41|  try {
42|    const { book, scenes } = loadOzBook();
43|    try {
44|      validateAgainstBook(
45|        parsed,
46|        {
47|          id: book.id,
48|          textVersion: book.textVersion,
49|          paragraphNs: new Set(book.paragraphs.map((p) => p.n)),
50|          sceneIds: new Set(scenes.map((s) => s.id)),
51|        },
52|      );
53|    } catch {
54|      return Response.json(
55|        { status: "error", code: "bad_request", message: MSG_BAD_REQUEST } satisfies ImageResponse,
56|        { status: 400 },
57|      );
58|    }
59|
60|    const byN = new Map(book.paragraphs.map((p) => [p.n, p.text]));
61|    const sceneOf = scenes.find((s) =>
62|      parsed.kind === "passage" ? parsed.n >= s.start_n && parsed.n <= s.end_n : s.id === parsed.sceneId,
63|    );
64|    const sceneParas = sceneOf
65|      ? book.paragraphs.filter((p) => p.n >= sceneOf.start_n && p.n <= sceneOf.end_n)
66|      : [];
67|    const content: ImageContent = {
68|      passageText: parsed.kind === "passage" ? (byN.get(parsed.n) ?? "") : "",
69|      sceneTitle: sceneOf?.title ?? "",
70|      sceneClip: sceneParas.map((p) => p.text).join(" "),
71|    };
72|
73|    const cookieValue = parseAnonCookie(req.headers.get("cookie"));
74|    let anonId = cookieValue ? verifyAnonCookie(cookieValue, env.sessionSecret) : null;
75|    let setCookie: string | null = null;
76|    if (!anonId) {
77|      const issued = issueAnonId(env.sessionSecret);
78|      anonId = issued.id;
79|      setCookie = serializeAnonCookie(issued.value);
80|    }
81|
82|    const res = await orchestrate(parsed, {
83|      kv: createRestKV(env.upstashUrl, env.upstashToken),
84|      store: createBlobStore(),
85|      generate: createMetaClient(env.metaKey),
86|      env,
87|      content,
88|      ip: clientIp(req.headers.get("x-forwarded-for")),
89|      anonId,
90|      day: utcDay(),
91|    });
92|
93|    const { json, status } = toResponse(res);
94|    const headers = setCookie ? { "Set-Cookie": setCookie } : undefined;
95|    return Response.json(json, { status, headers });
96|  } catch {
97|    console.error("image request failed");
98|    return Response.json(
99|      { status: "error", code: "unavailable", message: MSG_UNAVAILABLE } satisfies ImageResponse,
100|      { status: 503 },
101|    );
102|  }
