1|import "server-only";
2|
3|// Reads image env once per request. Any missing key means unavailable:
4|// with no quotas or budget configured, the route must never spend.
5|export interface ImageEnv {
6|  upstashUrl: string;
7|  upstashToken: string;
8|  metaKey: string;
9|  sessionSecret: string;
10|  ipSalt: string;
11|  spendCapMicro: number;
12|}
13|
14|// Vercel's Upstash marketplace integration injects KV_REST_API_* names.
15|// UPSTASH_* wins when non-empty, else the KV_* fallback applies per value.
16|// The read-only token is never used (we write).
17|const URL_NAMES = "UPSTASH_REDIS_REST_URL|KV_REST_API_URL";
18|const TOKEN_NAMES = "UPSTASH_REDIS_REST_TOKEN|KV_REST_API_TOKEN";
19|
20|const REQUIRED = [
21|  "BLOB_READ_WRITE_TOKEN",
22|  "META_API_KEY",
23|  "SESSION_SECRET",
24|  "IP_HASH_SALT",
25|] as const;
26|
27|export function readImageEnv(from: NodeJS.ProcessEnv = process.env): ImageEnv {
28|  const upstashUrl = from.UPSTASH_REDIS_REST_URL || from.KV_REST_API_URL;
29|  const upstashToken = from.UPSTASH_REDIS_REST_TOKEN || from.KV_REST_API_TOKEN;
30|  const missing = [
31|    upstashUrl ? null : URL_NAMES,
32|    upstashToken ? null : TOKEN_NAMES,
33|    ...REQUIRED.filter((k) => !from[k]),
34|  ].filter((m): m is string => m !== null);
35|  if (missing.length > 0) throw new Error(`missing image env: ${missing.join(",")}`);
36|  const capUsd = Number(from.SPEND_CAP_USD ?? "10");
37|  return {
38|    upstashUrl: upstashUrl as string,
39|    upstashToken: upstashToken as string,
40|    metaKey: from.META_API_KEY as string,
41|    sessionSecret: from.SESSION_SECRET as string,
42|    ipSalt: from.IP_HASH_SALT as string,
43|    spendCapMicro: Math.round((Number.isFinite(capUsd) ? capUsd : 10) * 1_000_000),
44|  };
45|}

