1|import { afterEach, beforeEach, describe, expect, it } from "vitest";
2|import { readImageEnv } from "./env";
3|
4|const BASE = {
5|  BLOB_READ_WRITE_TOKEN: "test-blob",
6|  META_API_KEY: "test-meta",
7|  SESSION_SECRET: "test-session",
8|  IP_HASH_SALT: "test-salt",
9|} as const;
10|
11|const REDIS_KEYS = [
12|  "UPSTASH_REDIS_REST_URL",
13|  "UPSTASH_REDIS_REST_TOKEN",
14|  "KV_REST_API_URL",
15|  "KV_REST_API_TOKEN",
16|  "KV_REST_API_READ_ONLY_TOKEN",
17|] as const;
18|
19|let saved: Record<string, string | undefined>;
20|
21|beforeEach(() => {
22|  saved = {};
23|  for (const k of [...Object.keys(BASE), ...REDIS_KEYS]) saved[k] = process.env[k];
24|  Object.assign(process.env, BASE);
25|  for (const k of REDIS_KEYS) delete process.env[k];
