27|
28|afterEach(() => {
29|  for (const k of Object.keys(saved)) {
30|    if (saved[k] === undefined) delete process.env[k];
31|    else process.env[k] = saved[k];
32|  }
33|});
34|
35|describe("readImageEnv redis fallback", () => {
36|  it("prefers UPSTASH_* when both are set", () => {
37|    process.env.UPSTASH_REDIS_REST_URL = "https://upstash-url";
38|    process.env.UPSTASH_REDIS_REST_TOKEN = "upstash-token";
39|    process.env.KV_REST_API_URL = "https://kv-url";
