48|    process.env.KV_REST_API_TOKEN = "kv-token";
49|    const env = readImageEnv();
50|    expect(env.upstashUrl).toBe("https://kv-url");
51|    expect(env.upstashToken).toBe("kv-token");
52|  });
53|
54|  it("uses KV_REST_API_* when UPSTASH_* is empty", () => {
55|    process.env.UPSTASH_REDIS_REST_URL = "";
56|    process.env.UPSTASH_REDIS_REST_TOKEN = "";
57|    process.env.KV_REST_API_URL = "https://kv-url";
58|    process.env.KV_REST_API_TOKEN = "kv-token";
