65|    process.env.UPSTASH_REDIS_REST_URL = "https://upstash-url";
66|    process.env.KV_REST_API_TOKEN = "kv-token";
67|    const env = readImageEnv();
68|    expect(env.upstashUrl).toBe("https://upstash-url");
69|    expect(env.upstashToken).toBe("kv-token");
70|  });
71|
72|  it("does not accept the read-only token alone", () => {
73|    process.env.KV_REST_API_URL = "https://kv-url";
