6|export function createRestKV(url: string, token: string): KV {
7|  async function cmd<T>(args: (string | number)[]): Promise<T> {
8|    const res = await fetch(url, {
9|      method: "POST",
10|      headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
11|      body: JSON.stringify(args),
12|    });
13|    if (!res.ok) throw new Error(`kv status ${res.status}`);
14|    const json = (await res.json()) as { result?: T; error?: string };
15|    if (json.error !== undefined) throw new Error("kv error");
16|    return json.result as T;
17|  }
18|  return {
19|    get: (key) => cmd<string | null>(["GET", key]),
20|    setNxEx: async (key, value, exSec) =>
21|      (await cmd<string | null>(["SET", key, value, "NX", "EX", exSec])) === "OK",
22|    set: async (key, value) => {
23|      await cmd(["SET", key, value]);
24|    },
25|    incr: (key) => cmd<number>(["INCR", key]),
26|    incrBy: (key, by) => cmd<number>(["INCRBY", key, by]),
