29|    expire: async (key, sec) => {
30|      await cmd(["EXPIRE", key, sec]);
31|    },
32|    // Lua compare-and-delete: an expired lock must not free a new owner.
33|    releaseIfToken: async (key, tokenValue) =>
34|      (await cmd<number>([
